/**
 * Jinx Lil' Monsta + Vizier: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * Wiki: https://wiki.bloodontheclocktower.com/Vizier
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L116). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { executionSavers, protection } from '#lib/core/rules/ability.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { babysits, scriptOf, withLilMonsta } from './lilmonsta.test-support.ts';

describe("Lil' Monsta + Vizier jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lilmonsta', 'vizier');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(data.byId.get('vizier')?.name).toBe('Vizier');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lilmonsta', 'vizier'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vizier'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Vizier can't die by day, but while babysitting Lil' Monsta
	// an execution kills them.
	describe('a Vizier babysitting Lil’ Monsta dies when executed', () => {
		const cast = ['vizier', 'poisoner', 'chef', 'empath', 'monk', 'mayor'];
		const base = withLilMonsta(cast);

		it("is data in the Vizier's rules", () => {
			expect(jinxRulesBetween('vizier', 'lilmonsta')).toEqual({
				diesWhenExecuted: 'Is The Demon'
			});
		});

		it('survives execution while not babysitting', () => {
			// Wiki: "If the Vizier is babysitting Lil' Monsta, they die when executed."
			const vizier = base.seat('vizier');
			expect(protection(base.game, vizier, base.characters, 'execution')).toEqual({
				characterId: 'vizier',
				seatId: vizier
			});
			expect(base.nominate('chef', 'vizier').execute('vizier').game.seats[vizier].dead).toBe(false);
		});

		it('dies when executed while babysitting, and good wins', () => {
			// Wiki: "If the Vizier is babysitting Lil' Monsta, they die when executed."
			const s = babysits(base, 'vizier');
			const vizier = s.seat('vizier');
			expect(protection(s.game, vizier, s.characters, 'execution')).toBeUndefined();
			expect(
				executionSavers(s.game, vizier, s.characters).find((x) => x.source.characterId === 'vizier')
					?.problem
			).toBe('jinxed');
			const executed = s.nominate('chef', 'vizier').execute('vizier');
			expect(executed.game.seats[vizier].dead).toBe(true);
			expect(gameEnds(executed.game, executed.characters)).toMatchObject([
				{ rule: 'demon-dead', winner: 'good', seats: [vizier] }
			]);
		});

		it('still cannot die by day to anything but an execution', () => {
			// Wiki: "If the Vizier is babysitting Lil' Monsta, they die when executed."
			const s = babysits(base, 'vizier');
			expect(protection(s.game, s.seat('vizier'), s.characters, 'day')).toEqual({
				characterId: 'vizier',
				seatId: s.seat('vizier')
			});
		});

		it('does not apply with no Lil’ Monsta on the script', () => {
			const plain = scenario(cast, { script: scriptOf(cast) }).reminder(
				'vizier',
				'lilmonsta',
				'Is The Demon'
			);
			const vizier = plain.seat('vizier');
			expect(protection(plain.game, vizier, plain.characters, 'execution')).toEqual({
				characterId: 'vizier',
				seatId: vizier
			});
		});
	});
});
